package com.playbox.games.model

object GameRules {
    fun forGame(id: GameId): String = when (id) {
        GameId.NUTS_BOLTS -> "Нажимайте на болт, чтобы поднять верхнюю гайку, и переложите её на пустой болт или на гайку того же цвета. Соберите на каждом болте один цвет."
        GameId.PETDOKU -> "Ставьте питомцев в пустые клетки поля 4×4 так, чтобы одинаковые не повторялись в строке, столбце и квадрате 2×2. Побеждает тот, кто сделает последний ход."
        GameId.MULTI_SNAKES -> "Ведите змейку пальцем от центра экрана, собирайте светящиеся сферы для роста и подрезайте соперников, чтобы они врезались в ваше тело."
        GameId.ARROWS_PUZZLE -> "Нажимайте на стрелки, путь перед которыми свободен до края поля. Очистите всё поле!"
        GameId.PAINT_MAZE -> "Свайпайте в любом направлении — шар катится до ближайшей стенки и закрашивает путь. Закрасьте 100% лабиринта."
        GameId.SHIKAKU -> "Проведите пальцем (или нажмите два угла), чтобы выделить прямоугольник с одним числом внутри. Площадь прямоугольника должна равняться этому числу."
        GameId.NUMBER_MATCH -> "Нажимайте на пары одинаковых чисел или чисел, дающих в сумме 10, стоящих рядом по прямой, диагонали или через пустые клетки."
        GameId.COLOR_BLOCKS -> "Управляйте падающими фигурами: двигайте влево/вправо, поворачивайте и сбрасывайте вниз. Заполненные горизонтальные линии исчезают."
        GameId.GUESS_WHO -> "Задавайте вопросы о признаках внешности (очки, шляпа, борода, светлые волосы) и отсеивайте лишних персонажей, чтобы первым угадать загаданного."
        GameId.FRUIT_MERGE -> "Ведите палец для прицела и отпускайте, чтобы бросить фрукт. Одинаковые фрукты при касании сливаются в более крупный фрукт до самого Арбуза!"
        GameId.ESCAPE_PARKING -> "Двигайте машины пальцем или кнопками вдоль их оси, чтобы освободить проезд и вывести красный грузовик к правому краю."
        GameId.BALL_RUN -> "Двигайте палец влево и вправо, чтобы шар уклонялся от неоновых препятствий в тоннеле."
        GameId.MULTI_COLOR_FILL -> "Выберите цвет сверху и нажимайте на соседние серые клетки, чтобы расширить цветную территорию и заполнить всё поле."
        GameId.TOWER_STACK -> "Нажимайте на экран в момент, когда движущийся блок находится точно над башней. Лишние края отсекаются!"
        GameId.WATER_SORT -> "Нажимайте на пробирку, затем на другую, чтобы перелить верхний слой воды того же цвета. Соберите по одному цвету в каждой пробирке."
        GameId.ANIMAL_STACK -> "Бросайте зверюшек точно друг на друга, удерживая равновесие башни как можно выше."
        GameId.DOMINO -> "Выкладывайте костяшки, совпадающие по точкам с одним из концов цепочки. Если подходящей костяшки нет — берите с базара. Побеждает сбросивший все первым."
        GameId.FALLING_SAND -> "Управляйте падающими песчаными блоками. Попадая на дно, они рассыпаются на песчинки; сплошной мостик одного цвета от левого края до правого исчезает!"
        GameId.WORD_SEARCH -> "Проводите по буквам в колесе (или нажимайте по очереди), чтобы составить все загаданные слова."
        GameId.ARCHERY -> "Прицел плавно движется — нажмите на экран точно в момент наведения на центр мишени (10 очков). Раунд из 5 выстрелов."
        GameId.DARTS -> "Классический дартс 301: списывайте очки точными бросками в сектора, удвоения, утроения и центр (25/50), пока не дойдёте ровно до 0."
        GameId.DROP_MERGE -> "Нажимайте на нужную колонку, чтобы бросить числовой блок. Одинаковые соседние блоки сливаются и удваиваются!"
        GameId.CROSS_SUMS -> "Включайте и выключайте клетки с числами так, чтобы сумма отмеченных чисел в каждой строке и каждом столбце совпала с целевым числом на рамке."
        GameId.CONNECT_2248 -> "Тяните палец по цепочке одинаковых чисел (или переходите на удвоенное), чтобы объединить их в крупное число."
        GameId.COLOR_CARDS -> "Сбрасывайте карту того же цвета или значения, что и верхняя на столе. Используйте +2, Пропуск, Смену и Дикие карты (+4)!"
        GameId.FLOW_COLORS -> "Тяните линии между парами цветных точек так, чтобы трубы не пересекали друг друга."
        GameId.FREECELL -> "Переносите все карты в дома (Туз → Король по мастям), используя 4 свободные ячейки и чередующиеся цвета в столбцах."
        GameId.LUDO -> "Бросайте кубик: 6 выводит фишку со старта и даёт повторный бросок. Сбивайте чужие фишки и приведите все 4 в центр первым."
        GameId.SOLITAIRE -> "Складывайте карты в столбцы по убыванию с чередованием красной/чёрной масти и отправляйте в 4 дома от Туза до Короля."
        GameId.SUDOKU -> "Заполните сетку 9×9 цифрами 1–9 так, чтобы они не повторялись ни в строке, ни в столбце, ни в блоке 3×3. Доступен режим заметок."
        GameId.HEARTS -> "Избегайте взяток с червами (1 очко) и особенно Дамой пик (13 очков). Побеждает игрок с наименьшим количеством штрафных очков."
        GameId.REVERSI -> "Ставьте фишку так, чтобы зажать фишки соперника по прямой или диагонали — они перевернутся в ваш цвет. Побеждает тот, чьих фишек больше."
        GameId.TAP_MATCH -> "Нажимайте на доступные верхние плитки, чтобы собрать тройки одинаковых в нижнем лотке (не более 7 плиток в лотке)."
        GameId.BATTLESHIP -> "Расставьте флот 10×10 и по очереди стреляйте по координатам соперника, пока не потопите все 10 кораблей."
        GameId.SOCCER_POOL -> "Оттяните свою фишку как рогатку и отпустите, чтобы ударить по мячу и забить 3 гола в ворота соперника!"
        GameId.GAME_2048 -> "Свайпайте в любую сторону, сдвигая плитки: одинаковые числа складываются и удваиваются. Цель — собрать плитку 2048!"
        GameId.CONNECT4 -> "Бросайте фишки в колонки сверху: побеждает тот, кто первым соберёт 4 фишки в ряд по горизонтали, вертикали или диагонали."
        GameId.TICTACTOE -> "Ставьте X или O на поле 3×3 (3 в ряд) или 5×5 (4 в ряд) и соберите линию быстрее соперника."
        GameId.BACKGAMMON -> "Бросайте кубики и проводите все 15 шашек в свой дом, затем выводите их за пределы доски. Одиночные шашки соперника можно сбить на бар."
        GameId.WORDLE -> "Угадайте загаданное слово из 5 букв за 6 попыток: зелёная буква — на месте, жёлтая — есть в слове, но в другом месте."
        GameId.MINESWEEPER -> "Открывайте безопасные клетки, опираясь на числа (сколько мин вокруг). Удерживайте клетку или переключите режим 🚩, чтобы отметить мину."
        GameId.HANGMAN -> "Выбирайте буквы по одной, чтобы отгадать скрытое слово раньше, чем будет дорисован человечек (6 ошибок)."
        GameId.SOUND_MEMORY -> "Запоминайте последовательность цветных секторов и звуков и повторяйте её безошибочно!"
        GameId.SNAKE -> "Управляйте змейкой, собирайте яблоки и не врезайтесь в стены, собственный хвост или вторую змейку."
        GameId.CHESS -> "Классические шахматы с шахом, матом, рокировкой и превращением пешек. Поставьте мат королю соперника."
        GameId.CHESS_PUZZLES -> "Найдите единственный точный тактический ход белых, ведущий к мату или решающему перевесу."
        GameId.CHECKERS -> "Двигайтесь по тёмным клеткам по диагонали, обязательно бейте шашки соперника и дойдите до дамок."
        GameId.BILLIARDS -> "Оттяните белый шар кием и забивайте свои шары в угловые лузы. В конце забейте чёрный шар №8!"
        GameId.MEMORY_CARDS -> "Открывайте по две карточки за ход и запоминайте их расположение, чтобы собрать все пары."
        GameId.SLIDING_PUZZLE -> "Передвигайте плитки в пустую клетку, чтобы выстроить все числа по порядку от 1 до 15."
        GameId.PING_PONG -> "Отбивайте мяч ракеткой, меняя угол отскока. Забейте 7 голов сопернику!"
        GameId.WOOD_BLOCKS -> "Размещайте деревянные фигуры на поле 9×9 и очищайте строки, столбцы и квадраты 3×3."
        GameId.DOTS_BOXES -> "Соединяйте соседние точки линиями. Замкнувший квадрат забирает его себе и получает дополнительный ход!"
        GameId.MANCALA -> "Выбирайте лунку на своей стороне, чтобы раскладывать камни против часовой стрелки. Последний камень в своём доме (калахе) даёт ещё один ход!"
    }
}
